using Netrunner.Core;

namespace Netrunner.Match;

/// <summary>
/// Harness-owned position setup. Roles never become physical IDs or agent inputs;
/// all pending decisions/actions are subsequently generated by Core.
/// </summary>
internal sealed class TacticalBoard
{
    private readonly GameState _basis;
    private readonly StableIdAllocator _allocator;
    private readonly List<CardInstanceState> _cards = [];
    private readonly List<ZoneState> _zones;
    private readonly List<ServerState> _servers;
    private readonly Dictionary<string, CardInstanceId> _roles = new(StringComparer.Ordinal);
    private readonly Dictionary<string, ServerId> _serverRoles = new(StringComparer.Ordinal);
    private readonly List<CardCounterState> _counters = [];
    private readonly HashSet<ZoneKind> _reversedZones = [];

    public TacticalBoard(IBehaviorCatalog behavior, IRuntimeCardCatalog runtime, string dataVersion, ulong seed = 502)
    {
        Behavior = behavior;
        Runtime = runtime;
        _basis = GameState.CreateNew(seed, cardDataVersion: dataVersion, behaviorRegistryVersion: behavior.Version,
            behaviorCatalogFingerprint: behavior.Fingerprint, runtimeCardCatalogVersion: runtime.Version, runtimeCardCatalogFingerprint: runtime.Fingerprint);
        _allocator = new(_basis.Allocator);
        _zones = [.. _basis.Zones];
        _servers = [.. _basis.Servers];
        _serverRoles.Add("hq", _servers.Single(server => server.Kind == ServerKind.Headquarters).Id);
        _serverRoles.Add("rd", _servers.Single(server => server.Kind == ServerKind.RAndD).Id);
        _serverRoles.Add("archives", _servers.Single(server => server.Kind == ServerKind.Archives).Id);
    }

    public IBehaviorCatalog Behavior { get; }
    public IRuntimeCardCatalog Runtime { get; }
    public int CorpCredits { get; set; } = 5;
    public int RunnerCredits { get; set; } = 5;
    public int CorpClicks { get; set; } = 3;
    public int RunnerClicks { get; set; } = 4;
    public int CorpPoints { get; set; }
    public int RunnerPoints { get; set; }
    public int RunnerTags { get; set; }
    public int RunnerMemory { get; set; } = 4;
    public int TurnNumber { get; set; } = 1;
    public TurnFactsState? PreviousRunnerTurn { get; set; }
    public bool SuccessfulRun { get; set; }
    public List<string> AttemptedServers { get; } = [];
    public List<string> SuccessfulServers { get; } = [];
    public List<string> InstalledThisTurn { get; } = [];
    public List<string> ProgramsInstalledThisTurn { get; } = [];
    public List<AgendaTurnChange> AgendaChanges { get; } = [];

    public CardInstanceId Card(string role) => _roles[role];
    public TacticalBoard Reverse(ZoneKind zone) { _reversedZones.Add(zone); return this; }
    public ServerId Server(string role)
    {
        if (_serverRoles.TryGetValue(role, out ServerId id)) return id;
        id = _allocator.NextServerId();
        ZoneId ice = _allocator.NextZoneId();
        ZoneId root = _allocator.NextZoneId();
        _servers.Add(new(id, ServerKind.Remote, ice, root));
        _zones.Add(new(ice, ZoneKind.ServerIce, PlayerSide.Corp, id));
        _zones.Add(new(root, ZoneKind.ServerRoot, PlayerSide.Corp, id));
        _serverRoles.Add(role, id);
        return id;
    }

    public TacticalBoard Add(string role, string code, ZoneKind zoneKind, string? server = null,
        bool rezzed = false, bool faceUp = false, int advancement = 0, string? host = null)
    {
        CardDefinitionId definition = new(code);
        CardRuntimeSpec spec = Runtime.GetSpec(definition);
        ZoneState zone;
        if (zoneKind is ZoneKind.ServerRoot or ZoneKind.ServerIce)
        {
            ServerId serverId = Server(server ?? "remote");
            zone = _zones.Single(value => value.ServerId == serverId && value.Kind == zoneKind);
        }
        else
        {
            zone = _zones.SingleOrDefault(value => value.Kind == zoneKind)
                ?? new ZoneState(_allocator.NextZoneId(), zoneKind, spec.Side);
            if (!_zones.Contains(zone)) _zones.Add(zone);
        }
        CardInstanceId id = _allocator.NextCardInstanceId();
        _roles.Add(role, id);
        bool visibleZone = zoneKind is ZoneKind.RunnerRig or ZoneKind.RunnerHeap or ZoneKind.CorpScore or ZoneKind.RunnerScore
            or ZoneKind.CorpIdentity or ZoneKind.RunnerIdentity;
        _cards.Add(new(id, definition, zone.Id, spec.Side, faceUp || rezzed || visibleZone, rezzed, advancement,
            hostCardId: host is null ? null : Card(host)));
        return this;
    }

    public TacticalBoard FillDecks(int corp = 12, int runner = 12)
    {
        // Deliberate scenario supplies, not hidden-deck priors for either agent.
        for (int index = 0; index < corp; index++) Add($"corp-deck-{index}", "30075", ZoneKind.CorpDeck);
        for (int index = 0; index < runner; index++) Add($"runner-deck-{index}", "30030", ZoneKind.RunnerStack);
        return this;
    }

    public TacticalBoard Counter(string role, string name, int amount, CardCounterPurpose purpose = CardCounterPurpose.Generic,
        HostedCreditSpendRestriction restriction = HostedCreditSpendRestriction.CardEffectOnly)
    {
        _counters.Add(purpose == CardCounterPurpose.Generic ? new(Card(role), name, amount)
            : new(Card(role), name, amount, purpose, purpose == CardCounterPurpose.HostedCredit ? restriction : null));
        return this;
    }

    public GameState Build(PlayerSide side, bool setup = false, bool discard = false)
    {
        PlayerState[] players = _basis.Players.Select(player => new PlayerState(player.Id, player.Side,
            player.Side == PlayerSide.Corp ? CorpCredits : RunnerCredits, setup ? 0 : player.Side == PlayerSide.Corp ? CorpClicks : RunnerClicks,
            player.Side == PlayerSide.Corp ? CorpPoints : RunnerPoints)).ToArray();
        PlayerId runner = players.Single(player => player.Side == PlayerSide.Runner).Id;
        ProgramMemoryState[] programs = _cards.Where(card => _zones.Single(zone => zone.Id == card.ZoneId).Kind == ZoneKind.RunnerRig
                && Runtime.GetSpec(card.DefinitionId).CardClass == RuntimeCardClass.Program)
            .Select(card => new ProgramMemoryState(card.Id, runner, Runtime.GetSpec(card.DefinitionId).MemoryUnits)).ToArray();
        var rules = new RulesState(1, players.Select(player => new PlayerRulesState(player.Id, 5, 0,
            player.Side == PlayerSide.Runner ? RunnerTags : 0, player.Side == PlayerSide.Runner ? RunnerMemory : 4,
            player.Side == PlayerSide.Runner ? programs.Sum(program => program.MemoryCost) : 0)).ToArray(), programs, _counters, [], [], []);
        var facts = new TurnFactsState(1, side, TurnNumber, side == PlayerSide.Corp ? 3 : 4, 0,
            !setup, !setup && side == PlayerSide.Corp, discard, false,
            installedCardIds: InstalledThisTurn.Select(Card).ToArray(), successfulRun: SuccessfulRun,
            attemptedRunServerIds: AttemptedServers.Select(Server).ToArray(), successfulRunServerIds: SuccessfulServers.Select(Server).ToArray(),
            programInstallOccurrenceIds: ProgramsInstalledThisTurn.Select(Card).ToArray(), agendaTurnChanges: AgendaChanges);
        // Core rolls a side's ThisTurn into LastTurn when that side next
        // begins a turn. During the Corp turn, RunnerThisTurn is therefore
        // the most recently completed Runner turn.
        TurnHistoryState? history = setup ? null : new(1, side == PlayerSide.Corp ? facts : null, null,
            side == PlayerSide.Runner ? facts : PreviousRunnerTurn, side == PlayerSide.Runner ? PreviousRunnerTurn : null);
        var turn = setup ? new TurnState(PlayerSide.Corp, TurnPhase.Setup)
            : new TurnState(side, side == PlayerSide.Corp ? TurnPhase.Corp : TurnPhase.Runner, TurnNumber,
                side == PlayerSide.Corp ? discard ? TurnStep.CorpDiscard : TurnStep.CorpAction : discard ? TurnStep.RunnerDiscard : TurnStep.RunnerAction, history);
        GameState state = new(_basis.SchemaVersion, _basis.GameId, _basis.RulesVersion, _basis.CardDataVersion, players,
            _cards, _zones.Select(zone => new ZoneState(zone.Id, zone.Kind, zone.OwnerSide, zone.ServerId, ZoneCards(zone))).ToArray(), _servers,
            turn, _basis.Outcome, _basis.RandomState, _allocator.State, initialSeed: _basis.InitialSeed, rulesState: rules,
            behaviorRegistryVersion: Behavior.Version, behaviorCatalogFingerprint: Behavior.Fingerprint,
            runtimeCardCatalogVersion: Runtime.Version, runtimeCardCatalogFingerprint: Runtime.Fingerprint);
        StateInvariantValidator.Validate(state, Behavior, Runtime);
        return state;

        CardInstanceId[] ZoneCards(ZoneState zone)
        {
            IEnumerable<CardInstanceId> ids = _cards.Where(card => card.ZoneId == zone.Id).Select(card => card.Id);
            return (_reversedZones.Contains(zone.Kind) ? ids.Reverse() : ids).ToArray();
        }
    }

    public GameState Action(PlayerSide side) => GameEngine.BeginResolution(Build(side),
        new TurnFrame(1, ResolutionBehaviorIds.Turn, side, TurnNumber, TurnFrameStage.AwaitingAction), Behavior, Runtime);

    public GameState Paid(PlayerSide side, PlayerSide priority) => GameEngine.BeginResolution(Build(side),
        new TurnFrame(1, ResolutionBehaviorIds.Turn, side, TurnNumber, TurnFrameStage.ActionPriority,
            side == PlayerSide.Corp ? TurnPriorityWindowKind.PaidRezAndScore : TurnPriorityWindowKind.PaidAndRez, priority), Behavior, Runtime);

    public GameState Discard(PlayerSide side) => GameEngine.BeginResolution(Build(side, discard: true),
        new TurnFrame(1, ResolutionBehaviorIds.Turn, side, TurnNumber, TurnFrameStage.DiscardSelection), Behavior, Runtime);

    public GameState Run(string server)
    {
        ServerId target = Server(server);
        return GameEngine.BeginRun(Build(PlayerSide.Runner), target, Behavior, Runtime);
    }

    public GameState Opening(PlayerSide side)
    {
        Identities();
        return GameEngine.BeginResolution(Build(side, setup: true), new SetupFrame(side), Behavior, Runtime);
    }

    public TacticalBoard Identities(string corp = "30077", string runner = "30076") =>
        Add("corp-identity", corp, ZoneKind.CorpIdentity).Add("runner-identity", runner, ZoneKind.RunnerIdentity);

    public ApplyResult Apply(GameState state, LegalAction action)
    {
        PendingDecision pending = state.PendingDecision ?? throw new InvalidOperationException("Tactical scenario has no decision.");
        if (!pending.LegalActions.Any(value => value.Id == action.Id)) throw new InvalidOperationException("Tactical action was not issued by Core.");
        ApplyResult result = GameEngine.Apply(state, new(pending.Owner, pending.Id, pending.Revision, action.Id), Behavior, Runtime);
        if (!result.Accepted) throw new InvalidOperationException(result.Rejection?.Message);
        StateInvariantValidator.Validate(result.State, Behavior, Runtime);
        return result;
    }

    public GameState Until(GameState state, Func<GameState, bool> stop, Func<GameState, LegalAction>? choose = null, int cap = 80)
    {
        for (int index = 0; !stop(state); index++)
        {
            if (index >= cap || state.PendingDecision is null) throw new InvalidOperationException("Tactical setup failed to reach its declared boundary.");
            state = Apply(state, choose?.Invoke(state) ?? Passive(state)).State;
        }
        return state;
    }

    public static LegalAction Passive(GameState state) => state.PendingDecision!.LegalActions.FirstOrDefault(action =>
        action.Kind is ActionKind.PassPriority or ActionKind.ContinueRun or ActionKind.NoAccessAction or ActionKind.DeclineTrigger or ActionKind.DeclinePrevention)
        ?? throw new InvalidOperationException($"Tactical opponent requires an explicit choice at {state.PendingDecision?.Kind}/{state.RunState?.Step}: {string.Join(',', state.PendingDecision!.LegalActions.Select(action => action.Kind))}.");
}
